    factor=2.0,
    exceptions=(Exception,),
):
    """Retry a callable with exponential backoff between attempts."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last_exc = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < max_retries - 1:
                        time.sleep(delay)
                        delay *= factor
            raise last_exc
        return wrapper
    return decorator

